interface EditorProps {
  isOpen: boolean;
  onClose: () => void;
  config: PortfolioConfig;
  onChange: (config: PortfolioConfig) => void;
}

export const Editor: React.FC<EditorProps> = ({ isOpen, onClose, config, onChange }) => {
  const [brokenImages, setBrokenImages] = useState<Record<string, boolean>>({});
  const [isFixing, setIsFixing] = useState<Record<string, boolean>>({});

  const handleChange = (key: keyof PortfolioConfig, value: any) => {
    onChange({ ...config, [key]: value });
  };

  // --- Image Validation Logic ---
  useEffect(() => {
    config.projects.forEach(project => {
      if (!project.imageUrl) {
         setBrokenImages(prev => ({ ...prev, [project.id]: false }));
         return;
      }
      // Check if URL is a data URI (assume valid) or runs check
      if (project.imageUrl.startsWith('data:')) {
          setBrokenImages(prev => ({ ...prev, [project.id]: false }));
          return;
      }

      const img = new Image();
      img.onload = () => setBrokenImages(prev => ({ ...prev, [project.id]: false }));
      img.onerror = () => setBrokenImages(prev => ({ ...prev, [project.id]: true }));
      img.src = project.imageUrl;
    });
  }, [config.projects]);

  // --- AI Repair Logic ---
  const handleAutoFix = async (index: number) => {
      const project = config.projects[index];
      setIsFixing(prev => ({ ...prev, [project.id]: true }));

      try {
          const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
          const response = await ai.models.generateContent({
              model: 'gemini-2.5-flash-image',
              contents: {
                  parts: [{ 
                      text: `Create a professional, abstract, high-quality portfolio thumbnail image for a design project titled "${project.title}". 
                             Description: ${project.description}. 
                             Style: Modern, minimalistic, geometric, architectural, high contrast. Do not include text.` 
                  }]
              },
              config: {
                  imageConfig: { aspectRatio: "4:3" }
              }
          });

          let newUrl = "";
          if (response.candidates?.[0]?.content?.parts) {
              for (const part of response.candidates[0].content.parts) {
                  if (part.inlineData) {
                      newUrl = `data:image/png;base64,${part.inlineData.data}`;
                      break;
                  }
              }
          }

          if (newUrl) {
              handleProjectChange(index, 'imageUrl', newUrl);
              setBrokenImages(prev => ({ ...prev, [project.id]: false }));
          } else {
              console.error("No image data found in response");
          }
      } catch (error) {
          console.error("Image generation failed:", error);
          alert("Failed to regenerate image. Please ensure your API key is valid.");
      } finally {
          setIsFixing(prev => ({ ...prev, [project.id]: false }));
      }
  };

  // --- Project Handlers ---
  const handleProjectChange = (index: number, field: keyof Project, value: string) => {
    const newProjects = [...config.projects];
    newProjects[index] = { ...newProjects[index], [field]: value };
    handleChange('projects', newProjects);
  };

  const addProject = () => {
    handleChange('projects', [...config.projects, { 
      id: Date.now().toString(), 
      title: "New Project", 
      category: "Design", 
      description: "Project description goes here.",
      imageUrl: "",
      projectUrl: ""
    }]);
  };

  const removeProject = (index: number) => {
    handleChange('projects', config.projects.filter((_, i) => i !== index));
  };

  // --- Experience Handlers ---
  const handleExpChange = (index: number, field: keyof ExperienceItem, value: string) => {
    const newExp = [...config.experience];
    newExp[index] = { ...newExp[index], [field]: value };
    handleChange('experience', newExp);
  };

  const addExp = () => {
    handleChange('experience', [...config.experience, {
      id: Date.now().toString(),
      year: "2025",
      role: "Role",
      company: "Company",
      description: "Description of responsibilities."
    }]);
  };

  const removeExp = (index: number) => {
    handleChange('experience', config.experience.filter((_, i) => i !== index));
  };

  // --- Publication Handlers ---
  const handlePubChange = (index: number, field: keyof Publication, value: string) => {
    const newPubs = [...(config.publications || [])];
    newPubs[index] = { ...newPubs[index], [field]: value };
    handleChange('publications', newPubs);
  };

  const addPub = () => {
    handleChange('publications', [...(config.publications || []), {
      id: Date.now().toString(),
      title: "New Paper",
      authors: config.name,
      journal: "Journal Name",
      year: new Date().getFullYear().toString(),
      doi: "",
      url: ""
    }]);
  };

  const removePub = (index: number) => {
    handleChange('publications', (config.publications || []).filter((_, i) => i !== index));
  };

  // --- Keyword Handler ---
  const handleKeywordsChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const val = e.target.value;
      const arr = val.split(',').map(k => k.trim());
      handleChange('keywords', arr);
  };

  // Export JSON-LD / Manifest for Platform
  const downloadManifest = () => {
    const manifest = {
        "@context": "https://schema.org",
        "@type": "ProfilePage",
        "dateCreated": new Date().toISOString(),
        "mainEntity": {
            "@type": "Person",
            "name": config.name,
            "description": config.bio,
            "identifier": config.orcid ? {
                "@type": "PropertyValue",
                "propertyID": "ORCID",
                "value": config.orcid
            } : undefined,
            "jobTitle": config.title,
            "knowsAbout": config.keywords,
            "url": window.location.href,
            "sameAs": [config.linkedin, config.github],
            "email": config.email
        },
        "hasPart": [
            ...config.projects.map(p => ({
                "@type": "CreativeWork",
                "name": p.title,
                "description": p.description,
                "url": p.projectUrl,
                "thumbnailUrl": p.imageUrl,
                "genre": p.category
            })),
            ...(config.publications || []).map(pub => ({
                "@type": "ScholarlyArticle",
                "headline": pub.title,
                "author": pub.authors,
                "publication": {
                    "@type": "Periodical",
                    "name": pub.journal
                },
                "datePublished": pub.year,
                "sameAs": pub.doi ? `https://doi.org/${pub.doi}` : pub.url,
                "identifier": pub.doi ? {
                    "@type": "PropertyValue",
                    "propertyID": "DOI",
                    "value": pub.doi
                } : undefined
            }))
        ]
    };

    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(manifest, null, 2));
    const downloadAnchorNode = document.createElement('a');
    downloadAnchorNode.setAttribute("href", dataStr);
    downloadAnchorNode.setAttribute("download", "researcher.json");
    document.body.appendChild(downloadAnchorNode);
    downloadAnchorNode.click();
    downloadAnchorNode.remove();
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-y-0 right-0 w-full md:w-[500px] bg-white shadow-2xl z-[60] overflow-y-auto border-l border-stone-200 animate-slide-in-right">
      <div className="sticky top-0 bg-white/95 backdrop-blur z-10 p-5 border-b border-stone-200 flex justify-between items-center">
        <h2 className="font-serif text-2xl text-stone-900 flex items-center gap-2">
           <Layout size={24} className="text-stone-500" />
           Portfolio Builder
        </h2>
        <button onClick={onClose} className="p-2 hover:bg-stone-100 rounded-full transition-colors text-stone-500">
          <X size={24} />
        </button>
      </div>

      <div className="p-6 space-y-10">

        {/* Template Selector */}
        <section className="space-y-4">
             <div className="flex items-center gap-2 text-xs font-bold text-stone-400 uppercase tracking-widest">
                <Monitor size={14} /> Design Template
            </div>
            <div className="grid grid-cols-3 gap-3">
                <button 
                    onClick={() => handleChange('template', 'classic')}
                    className={`relative p-3 rounded-lg border-2 text-left transition-all ${config.template === 'classic' ? 'border-stone-900 bg-stone-50' : 'border-stone-100 hover:border-stone-300'}`}
                >
                    <div className="w-6 h-6 rounded-full bg-[#F9F8F4] border border-stone-300 mb-2"></div>
                    <div className="font-serif font-bold text-stone-900">Classic</div>
                    <div className="text-[10px] text-stone-500">Elegant & Clean</div>
                    {config.template === 'classic' && <div className="absolute top-2 right-2 w-2 h-2 rounded-full bg-stone-900"></div>}
                </button>

                <button 
                    onClick={() => handleChange('template', 'cyber')}
                    className={`relative p-3 rounded-lg border-2 text-left transition-all ${config.template === 'cyber' ? 'border-cyan-500 bg-slate-900' : 'border-stone-100 hover:border-slate-700 hover:bg-slate-900 group'}`}
                >
                    <div className="w-6 h-6 rounded bg-slate-800 border border-cyan-500 mb-2"></div>
                    <div className={`font-mono font-bold ${config.template === 'cyber' || 'group-hover:text-white' ? 'text-white' : 'text-stone-900'}`}>Cyber</div>
                    <div className="text-[10px] text-stone-500">Dark & Neon</div>
                     {config.template === 'cyber' && <div className="absolute top-2 right-2 w-2 h-2 rounded-full bg-cyan-500"></div>}
                </button>

                <button 
                    onClick={() => handleChange('template', 'brutal')}
                    className={`relative p-3 rounded-lg border-2 text-left transition-all ${config.template === 'brutal' ? 'border-black bg-yellow-50' : 'border-stone-100 hover:border-black'}`}
                >
                    <div className="w-6 h-6 border-2 border-black bg-white mb-2 shadow-[2px_2px_0px_rgba(0,0,0,1)]"></div>
                    <div className="font-sans font-black text-black uppercase tracking-tight">Brutal</div>
                    <div className="text-[10px] text-stone-500">Bold & Raw</div>
                     {config.template === 'brutal' && <div className="absolute top-2 right-2 w-2 h-2 bg-black"></div>}
                </button>
            </div>
        </section>

        <hr className="border-stone-100" />

        {/* Profile Section */}
        <section className="space-y-4">
            <div className="flex items-center gap-2 text-xs font-bold text-stone-400 uppercase tracking-widest">
                <Type size={14} /> Profile & Hero
            </div>
            <div className="space-y-3">
                <div className="space-y-1">
                    <label className="text-xs font-medium text-stone-500">Full Name</label>
                    <input 
                        type="text" 
                        value={config.name} 
